import {parseSnapshot} from './snapshot.js';
import {loadSnapshot,replaceSnapshot} from './snapshot-store.js';
import {escapeHTML as e,memberCard} from './roster-view.js';
const $=s=>document.querySelector(s);let snapshot=null;
function render(){if(!snapshot)return;const p=snapshot,c=p.trainer;
 $('#snapshot-content').innerHTML=`<section class="card"><p class="eyebrow">Snapshot · exported ${e(new Date(p.exported_at).toLocaleString())}</p><h1>${e(c.name)}</h1><p>Level ${c.level} · XP ${c.xp_total}</p><div class="resources">${c.resources.map(r=>`<div class="resource"><span>${e(r.label)}</span><div class="big-number">${r.current} <span>/ ${r.max}</span></div>${r.current>r.max?'<p class="over-max">Current exceeds maximum</p>':''}</div>`).join('')}</div><p>${e(c.currency.label)} <strong>${c.currency.amount}</strong></p><div class="ref-grid">${c.attributes.map(a=>`<div class="attribute"><span>${e(a.label)}</span><strong>${e(a.value)}</strong><span>${e(a.note)}</span></div>`).join('')}</div>${c.ability_slots.map(slot=>`<h3>Slot ${slot.index} · ${e(slot.name||'Open')}</h3>${slot.applications.map(a=>`<details class="ability"><summary>${e(a.name)} · ${e(a.status==='not_recorded'?'Status not recorded':a.status.replaceAll('_',' '))}</summary><p>Cost: ${e(a.cost)}</p><p>Range: ${e(a.range)}</p><p>${e(a.effect)}</p><p>${e(a.notes)}</p></details>`).join('')}`).join('')}</section><h2>Active team</h2>${p.roster.filter(r=>r.member.status==='active').map(r=>memberCard(r.member,r.progress)).join('')||'<p>No active members.</p>'}<details class="card"><summary>Boxed members · ${p.roster.filter(r=>r.member.status==='boxed').length}</summary>${p.roster.filter(r=>r.member.status==='boxed').map(r=>memberCard(r.member,r.progress)).join('')}</details><section class="card"><h2>Inventory</h2>${p.inventory.map(i=>`<div class="row"><div><strong>${e(i.item)}</strong><p>${e(i.notes)}</p></div><span class="quantity">× ${i.qty}</span></div>`).join('')||'<p>No items recorded.</p>'}</section>`;
}
$('#snapshot-file').onchange=()=>{$('#load-snapshot').disabled=!$('#snapshot-file').files.length;$('#snapshot-error').textContent='';};
$('#load-snapshot').onclick=async()=>{const file=$('#snapshot-file').files[0];if(!file)return;$('#load-snapshot').disabled=true;$('#snapshot-file').disabled=true;$('#snapshot-error').textContent='';try{if(file.size>5*1024*1024)throw Error('Snapshot must be under 5 MB.');const incoming=parseSnapshot(await file.text());await replaceSnapshot(incoming);snapshot=incoming;try{localStorage.setItem('scroll-viewer-mode','1');}catch{}render();$('#snapshot-status').textContent='Latest imported snapshot saved on this device. Read only.';}catch(err){$('#snapshot-error').textContent=err.message;}finally{$('#load-snapshot').disabled=false;$('#snapshot-file').disabled=false;}};
try{snapshot=await loadSnapshot();render();}catch(e){$('#snapshot-error').textContent=e.message;}
if('serviceWorker'in navigator){try{await navigator.serviceWorker.register('./sw.js');await navigator.serviceWorker.ready;$('#offline-status').textContent='Offline ready · snapshots do not sync automatically.';}catch{$('#offline-status').textContent='Offline caching unavailable. Keep this page online.';}}
